func filterToggleOn(id string, f presenter.CatalogFilter) bool {
	switch id {
	case "free":
		return f.Free
	case "walkable":
		return f.Walkable
	case "kids":
		return f.Kids
	case "noCar":
		return f.NoCar
	case "swim":
		return f.Swim
	}

	return false
}

func filterMultiOn(id, value string, f presenter.CatalogFilter) bool {
	list := f.Difficulty
	if id == "beach" {
		list = f.Beach
	}
	for _, item := range list {
		if item == value {
			return true
		}
	}

	return false
}

func filterSingleOn(id, value string, f presenter.CatalogFilter) bool {
	if id != "distance" {
		return false
	}
	if value == "" {
		return f.Distance == 0
	}

	return strconv.FormatFloat(f.Distance, 'f', -1, 64) == value
}

